# Universal Result Delivery Manager demo: one result set, many renderings.
RESULTS=[{"id":"r1","title":"Solar Sails","score":0.94},{"id":"r2","title":"Kapton","score":0.81}]
def as_text(rs): return "\n".join("%s (%.2f) %s"%(r["id"],r["score"],r["title"]) for r in rs)
def as_json(rs):
    import json; return json.dumps(rs)
def as_csv(rs): return "id,title,score\n"+"".join("%s,%s,%.2f\n"%(r["id"],r["title"],r["score"]) for r in rs)
def as_links(rs,base="https://archive.example/db/"):
    return "\n".join(base+r["id"] for r in rs)
for name,fn in [("text",as_text),("json",as_json),("csv",as_csv),("links",as_links)]:
    print("---",name,"---"); print(fn(RESULTS))

